  rrs = [];
  for(let r=0; r<rrsL; r++){
    rrs.push(R.random_dec());
  }
}
function rr(){
  rroff++;
  rrvalue = rrs[rroff%rrsL];
  return rrvalue;
}
function rr1(){
  rroff++;
  rrvalue = (rrs[rroff%rrsL]-0.5)*2;
  return rrvalue;
}
function rr2(a,b){
  rroff++;
  rrvalue = a+rr()*(b-a);
  return rrvalue;
}
function rri(a){
  rroff++;
  rrvalue = floor(rr()*a);
  return rrvalue;
}
function rrarr(myArr){
  let temprs = [];
  for(let r = 0; r<myArr.length; r++){
    rroff++;
    newval = rr(rroff);
    temprs.push(newval);
  }
  volta = -1;
  maxV = Math.max(...temprs);
  tempV = maxV+1;
  while(tempV!=maxV){
    volta++;
    tempV = temprs[volta%temprs.length];
  }
  let chosen = myArr[volta%myArr.length];
  return chosen;
}
