function shuffleArray(tarray) {
array = [...tarray];
  for (let i = array.length - 1; i > 0; i--) {
      let j = Math.floor(R.random_dec() * (i + 1));
      [array[i], array[j]] = [array[j], array[i]];
  }
  return(array)
}
